mkitem!{mkimpl!{impl < BODY > HeapJob < BODY > where BODY : FnOnce (JobRefId) + Send , { pub (super) fn new (tlv : Tlv , job : BODY) -> Box < Self > { Box :: new (HeapJob { job , tlv }) } # [doc = " Creates a `JobRef` from this job -- note that this hides all"] # [doc = " lifetimes, so it is up to you to ensure that this JobRef"] # [doc = " doesn't outlive any data that it closes over."] pub (super) unsafe fn into_job_ref (self : Box < Self >) -> JobRef { unsafe { JobRef :: new (Box :: into_raw (self)) } } # [doc = " Creates a static `JobRef` from this job."] pub (super) fn into_static_job_ref (self : Box < Self >) -> JobRef where BODY : 'static , { unsafe { self . into_job_ref () } } }}}
mkitem!{mkimpl!{impl < BODY > Job for HeapJob < BODY > where BODY : FnOnce (JobRefId) + Send , { unsafe fn execute (this : * const ()) { let pointer = this . expose_provenance () ; let this = unsafe { Box :: from_raw (this as * mut Self) } ; tlv :: set (this . tlv) ; (this . job) (JobRefId { pointer }) ; } }}}
